<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserFederatedIdentity\Domain\ValueObject\Holder\UserFederatedIdentityLoginProviderAttributeHolder;
use Civi\Lughauth\Shared\Value\Validation\ConstraintFailList;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserFederatedIdentityLoginProviderAttributeHolder trait.
 *
 * Covers assignment, retrieval, default fallback,
 * transfer between holders, validation rules, and unset operations.
 */
class UserFederatedIdentityLoginProviderAttributeHolderUnitTest extends TestCase
{
    /**
     * Asserts that the code attribute is not assigned by default
     * and that getLoginProvider returns null on a freshly created holder.
     */
    public function testLoginProviderNotAssignedByDefault(): void
    {
        // Arrange
        $holder = new ImplWithUserFederatedIdentityLoginProviderAttributeHolderUnitTest();

        // Assert
        $this->assertFalse($holder->isLoginProviderAssigned());
        $this->assertNull($holder->getLoginProvider());
    }
}
class ImplWithUserFederatedIdentityLoginProviderAttributeHolderUnitTest
{
    use UserFederatedIdentityLoginProviderAttributeHolder;
    public function assertRules(ConstraintFailList $errorsList): self
    {
        $result = new self();
        $this->withAssertedLoginProviderRules($result, $errorsList);
        return $result;
    }

    public function applyDefaults(): void
    {
        $this->withDefaultLoginProvider();
    }
}
